// ignore_for_file: lines_longer_than_80_chars

/// Số đơn vị ứng với chiều cao khung vẽ.
const int kAnatomyUnits = 4000;

/// Một mảng của hình: [slug] là tên cơ gốc, [group] là nhóm cơ của app
/// (`chest`, `back`, `shoulders`, `arms`, `abs`, `glutes`, `legs`), hoặc
/// `body` (đầu, cổ, bàn tay, gối, bàn chân), `hair`.
class AnatomyPartData {
  const AnatomyPartData(this.slug, this.group, this.d);
  final String slug;
  final String group;
  final String d;
}

class AnatomyViewData {
  const AnatomyViewData({
    required this.outline,
    required this.parts,
    required this.pain,
  });

  /// Đường viền thân người.
  final String outline;
  final List<AnatomyPartData> parts;

  /// Tâm điểm đau theo tên vùng: dãy x, y nối tiếp (đơn vị như đường nét).
  final Map<String, List<int>> pain;
}

